from ta_moler.cmd.netactnode.genericnetactnode import GenericNetActNodeCommand
from moler.exceptions import ParsingDone
from moler.exceptions import CommandFailure
import re


class CpfSmanagerConfigure(GenericNetActNodeCommand):
    """CpfSmanagerConfigure command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Cpfsmanagerconfigure command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(CpfSmanagerConfigure, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                                   runner=runner)
        self.options = options
        self.current_ret["LOGS_FILE_PATH"] = None
        self.current_ret["WARNINGS"] = []

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "/opt/cpf/install/bin/cpfsmanager_configure.pl"
        cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise.
        :return: None.
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_warning(line)
                self._search_logs_path(line)
            except ParsingDone:
                pass

        return super(CpfSmanagerConfigure, self).on_new_line(line, is_full_line)

    # ERROR: Missing options or command
    _re_parse_error = re.compile(r'(?P<ERROR>ERROR: Missing options or command|Unknown option:.*)')

    def _parse_error(self, line):
        """
        Parse line if error.

        :param line: Line from device.
        :return: None but raises ParsingDone if matches error.
        """
        if self._regex_helper.search_compiled(CpfSmanagerConfigure._re_parse_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone

    # Can not create tar file on clab1364node19
    _re_parse_warning = re.compile(r'Can not create tar file on clab\d+node\d+|Can not create statistics report')

    def _parse_warning(self, line):
        """
        Parse line if warning.

        :param line: Line from device.
        :return: None but raises ParsingDone if matches warning.
        """
        if self._regex_helper.search_compiled(CpfSmanagerConfigure._re_parse_warning, line):
            self.current_ret["WARNINGS"].append(line)
            raise ParsingDone

    # /var/tmp/netact_smlogs.tar.bzip2
    _re_parse_logs_path = re.compile(r'(?P<FILE_PATH>(/[a-zA-Z0-9._-]+)+.bzip2)')

    def _search_logs_path(self, line):
        """
        Parse path to logs.

        :param line: Line from device.
        :return: None but raises ParsingDone if matches path to logs.
        """
        if self._regex_helper.search_compiled(CpfSmanagerConfigure._re_parse_logs_path, line):
            self.current_ret["LOGS_FILE_PATH"] = self._regex_helper.group('FILE_PATH')
            raise ParsingDone


